<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Northstar Retail | Dark Studio Home</title>
    <meta
      name="description"
      content="A polished dark ecommerce home page with featured products, deals, and editorial stories."
    />
    <style>
      :root {
        color-scheme: dark;
        --bg: #0a0d12;
        --bg-elevated: #11151d;
        --bg-surface: #151a23;
        --bg-surface-2: #1b2230;
        --border: #283144;
        --border-strong: #39465f;
        --text: #f3f7ff;
        --muted: #a8b3c7;
        --muted-2: #7d899e;
        --accent: #9bf7d3;
        --accent-2: #7aa7ff;
        --accent-3: #ffca7a;
        --danger: #ff7a90;
        --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
        --radius-xl: 30px;
        --radius-lg: 22px;
        --radius-md: 16px;
        --radius-sm: 12px;
        --max: 1180px;
      }

      * {
        box-sizing: border-box;
      }

      html {
        scroll-behavior: smooth;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font: 16px/1.5 Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, rgba(122, 167, 255, 0.22), transparent 34%),
          radial-gradient(circle at right top, rgba(155, 247, 211, 0.16), transparent 26%),
          linear-gradient(180deg, #0b0f16 0%, #090b10 100%);
      }

      a {
        color: inherit;
        text-decoration-thickness: 2px;
        text-underline-offset: 3px;
      }

      img {
        max-width: 100%;
        display: block;
      }

      button,
      input {
        font: inherit;
      }

      .skip-link {
        position: absolute;
        top: 0.75rem;
        left: 0.75rem;
        transform: translateY(-180%);
        padding: 0.85rem 1rem;
        border-radius: 999px;
        background: var(--accent);
        color: #06110d;
        text-decoration: none;
        font-weight: 700;
        z-index: 1000;
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid #fff;
        outline-offset: 2px;
      }

      .shell {
        width: min(100%, var(--max));
        margin: 0 auto;
        padding: 1rem 1rem 3rem;
      }

      header {
        position: sticky;
        top: 0;
        z-index: 20;
        backdrop-filter: blur(18px);
        background: linear-gradient(180deg, rgba(10, 13, 18, 0.96), rgba(10, 13, 18, 0.72));
        border-bottom: 1px solid rgba(57, 70, 95, 0.45);
      }

      .header-inner {
        width: min(100%, var(--max));
        margin: 0 auto;
        padding: 1rem;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 0.8rem;
        font-weight: 800;
        letter-spacing: 0.02em;
        text-decoration: none;
      }

      .brand-mark {
        width: 2.2rem;
        height: 2.2rem;
        border-radius: 14px;
        background: linear-gradient(135deg, var(--accent), var(--accent-2));
        box-shadow: 0 10px 30px rgba(122, 167, 255, 0.28);
      }

      nav ul {
        list-style: none;
        margin: 0;
        padding: 0;
        display: flex;
        flex-wrap: wrap;
        gap: 1rem;
      }

      nav a {
        color: var(--muted);
        text-decoration: none;
        padding: 0.6rem 0.8rem;
        border-radius: 999px;
      }

      nav a:hover,
      nav a:focus-visible {
        color: var(--text);
        background: rgba(255, 255, 255, 0.06);
        outline: none;
      }

      .hero {
        display: grid;
        grid-template-columns: 1.2fr 0.9fr;
        gap: 1.2rem;
        padding: 1.5rem 0 0.75rem;
        align-items: stretch;
      }

      .panel {
        background: linear-gradient(180deg, rgba(21, 26, 35, 0.94), rgba(15, 19, 27, 0.96));
        border: 1px solid var(--border);
        border-radius: var(--radius-xl);
        box-shadow: var(--shadow);
      }

      .hero-copy {
        padding: clamp(1.4rem, 4vw, 3rem);
        display: grid;
        gap: 1.25rem;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 0.55rem;
        width: fit-content;
        padding: 0.45rem 0.8rem;
        border: 1px solid var(--border);
        border-radius: 999px;
        color: var(--accent);
        background: rgba(155, 247, 211, 0.08);
        font-size: 0.92rem;
        font-weight: 700;
      }

      h1,
      h2,
      h3,
      p {
        margin: 0;
      }

      h1 {
        font-size: clamp(2.6rem, 6vw, 4.9rem);
        line-height: 0.96;
        letter-spacing: -0.04em;
        max-width: 11ch;
      }

      .hero-copy p {
        max-width: 58ch;
        color: var(--muted);
        font-size: 1.08rem;
      }

      .hero-actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.85rem;
      }

      .button,
      .button-secondary {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 0.55rem;
        min-height: 3rem;
        padding: 0.8rem 1.1rem;
        border-radius: 999px;
        border: 1px solid transparent;
        font-weight: 700;
        text-decoration: none;
      }

      .button {
        color: #06110d;
        background: linear-gradient(135deg, var(--accent), #c0ffe8);
      }

      .button-secondary {
        color: var(--text);
        border-color: var(--border-strong);
        background: rgba(255, 255, 255, 0.03);
      }

      .button:hover,
      .button-secondary:hover {
        transform: translateY(-1px);
      }

      .hero-stats {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 0.8rem;
      }

      .stat {
        padding: 1rem;
        border-radius: var(--radius-md);
        border: 1px solid var(--border);
        background: rgba(255, 255, 255, 0.03);
        min-width: 0;
      }

      .stat strong {
        display: block;
        font-size: 1.35rem;
      }

      .stat span {
        color: var(--muted);
        font-size: 0.94rem;
      }

      .hero-visual {
        padding: 1rem;
        display: grid;
        gap: 1rem;
        align-content: space-between;
        background:
          linear-gradient(180deg, rgba(17, 21, 29, 0.65), rgba(17, 21, 29, 0.92)),
          radial-gradient(circle at top, rgba(122, 167, 255, 0.22), transparent 60%);
      }

      .feature-card {
        position: relative;
        overflow: hidden;
        min-height: 100%;
        border-radius: calc(var(--radius-xl) - 8px);
        border: 1px solid var(--border);
        background:
          radial-gradient(circle at top left, rgba(155, 247, 211, 0.18), transparent 36%),
          linear-gradient(160deg, #1b2230 0%, #10151d 100%);
      }

      .feature-card .image {
        aspect-ratio: 4 / 3;
        display: grid;
        place-items: center;
        background:
          radial-gradient(circle at 30% 20%, rgba(255, 202, 122, 0.2), transparent 24%),
          radial-gradient(circle at 70% 65%, rgba(122, 167, 255, 0.26), transparent 25%);
        border-bottom: 1px solid rgba(57, 70, 95, 0.4);
      }

      .feature-card .content {
        padding: 1rem 1rem 1.1rem;
      }

      .pill-row {
        display: flex;
        flex-wrap: wrap;
        gap: 0.5rem;
      }

      .pill {
        border-radius: 999px;
        padding: 0.42rem 0.7rem;
        border: 1px solid var(--border);
        color: var(--muted);
        font-size: 0.88rem;
      }

      .section {
        padding-top: 1.5rem;
      }

      .section-header {
        display: flex;
        align-items: end;
        justify-content: space-between;
        gap: 1rem;
        margin-bottom: 0.95rem;
      }

      .section-header p {
        color: var(--muted);
        max-width: 55ch;
      }

      .section-header a {
        color: var(--accent);
        text-decoration: none;
        font-weight: 700;
      }

      .grid-products {
        display: grid;
        grid-template-columns: repeat(4, minmax(0, 1fr));
        gap: 1rem;
      }

      .card {
        min-width: 0;
        border-radius: var(--radius-lg);
        border: 1px solid var(--border);
        background: linear-gradient(180deg, rgba(21, 26, 35, 0.92), rgba(14, 17, 24, 0.96));
        overflow: hidden;
      }

      .card figure {
        margin: 0;
      }

      .card .art {
        display: grid;
        place-items: center;
        aspect-ratio: 1 / 1;
        border-bottom: 1px solid rgba(57, 70, 95, 0.4);
        background:
          radial-gradient(circle at 35% 30%, rgba(155, 247, 211, 0.18), transparent 18%),
          radial-gradient(circle at 70% 75%, rgba(122, 167, 255, 0.22), transparent 22%),
          linear-gradient(145deg, #151b25 0%, #0f131b 100%);
      }

      .card .body {
        padding: 1rem;
        display: grid;
        gap: 0.8rem;
      }

      .meta,
      .price-row {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 0.75rem;
      }

      .meta {
        color: var(--muted);
        font-size: 0.92rem;
      }

      .price {
        font-weight: 800;
        font-size: 1.08rem;
      }

      .strike {
        color: var(--muted-2);
        text-decoration: line-through;
      }

      .deal-grid {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 1rem;
      }

      .deal {
        padding: 1.2rem;
        display: grid;
        gap: 1rem;
        border-radius: var(--radius-lg);
        border: 1px solid var(--border);
        background:
