      .deal .cta {
        margin-top: auto;
        display: inline-flex;
        width: fit-content;
        align-items: center;
        gap: 0.45rem;
        color: var(--text);
        font-weight: 700;
        text-decoration: none;
      }

      .editorial-grid {
        display: grid;
        grid-template-columns: 1.1fr 0.9fr 0.9fr;
        gap: 1rem;
      }

      .story {
        overflow: hidden;
      }

      .story .image {
        aspect-ratio: 16 / 9;
        background:
          radial-gradient(circle at 25% 35%, rgba(255, 202, 122, 0.22), transparent 16%),
          radial-gradient(circle at 75% 30%, rgba(155, 247, 211, 0.22), transparent 20%),
