      .newsletter {
        margin-top: 1.5rem;
        padding: 1.2rem;
        display: grid;
        gap: 1rem;
        border-radius: var(--radius-lg);
        border: 1px solid var(--border);
        background: linear-gradient(135deg, rgba(122, 167, 255, 0.12), rgba(155, 247, 211, 0.06));
      }

      form {
        display: flex;
        flex-wrap: wrap;
        gap: 0.8rem;
      }

      label {
        display: grid;
        gap: 0.35rem;
        color: var(--muted);
        font-weight: 600;
      }

      input[type="email"] {
        min-width: min(100%, 22rem);
        flex: 1 1 20rem;
        min-height: 3rem;
        padding: 0.8rem 1rem;
        color: var(--text);
        border-radius: 999px;
        border: 1px solid var(--border-strong);
        background: rgba(8, 11, 16, 0.92);
      }

      input[type="email"]::placeholder {
        color: var(--muted-2);
      }

      input[type="email"]:focus-visible,
