      .button-secondary:focus-visible,
      .cta:focus-visible,
      a:focus-visible {
        outline: 3px solid var(--accent);
        outline-offset: 3px;
      }

      .helper {
        color: var(--muted-2);
        font-size: 0.92rem;
      }

      footer {
        padding: 2rem 1rem 1rem;
        color: var(--muted);
      }

      .footer-inner {
        width: min(100%, var(--max));
        margin: 0 auto;
        padding-top: 1.25rem;
        border-top: 1px solid rgba(57, 70, 95, 0.5);
        display: flex;
        flex-wrap: wrap;
        justify-content: space-between;
        gap: 1rem;
      }

      .fineprint {
        max-width: 52ch;
      }

      svg {
        display: block;
      }

      .visual-svg {
        width: min(100%, 17rem);
      }

      @media (max-width: 1000px) {
        .hero,
        .grid-products,
        .editorial-grid {
          grid-template-columns: 1fr 1fr;
