        .hero {
          grid-template-columns: 1fr;
        }

        .hero-visual {
          min-height: 28rem;
        }
      }

      @media (max-width: 720px) {
        .header-inner,
        .section-header,
        .footer-inner {
          align-items: start;
          flex-direction: column;
        }

        nav ul {
          gap: 0.5rem;
        }

        .hero-stats,
        .grid-products,
        .deal-grid,
        .editorial-grid {
          grid-template-columns: 1fr;
        }

        h1 {
          max-width: none;
        }
      }

      @media (forced-colors: active) {
