<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Northstar Retail | Dark Studio Home</title>
    <meta
      name="description"
      content="A polished dark ecommerce home page with featured products, deals, and editorial stories."
    />
    <style>
      :root {
        color-scheme: dark;
        --bg: #0a0d12;
        --bg-elevated: #11151d;
        --bg-surface: #151a23;
        --bg-surface-2: #1b2230;
        --border: #283144;
        --border-strong: #39465f;
        --text: #f3f7ff;
        --muted: #a8b3c7;
