        --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
        --radius-xl: 30px;
        --radius-lg: 22px;
        --radius-md: 16px;
        --radius-sm: 12px;
        --max: 1180px;
      }

      * {
        box-sizing: border-box;
      }

      html {
        scroll-behavior: smooth;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font: 16px/1.5 Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, rgba(122, 167, 255, 0.22), transparent 34%),
          radial-gradient(circle at right top, rgba(155, 247, 211, 0.16), transparent 26%),
          linear-gradient(180deg, #0b0f16 0%, #090b10 100%);
      }

      a {
        color: inherit;
        text-decoration-thickness: 2px;
        text-underline-offset: 3px;
      }

      img {
        max-width: 100%;
        display: block;
      }

      button,
      input {
        font: inherit;
      }

      .skip-link {
        position: absolute;
        top: 0.75rem;
        left: 0.75rem;
        transform: translateY(-180%);
        padding: 0.85rem 1rem;
        border-radius: 999px;
        background: var(--accent);
        color: #06110d;
        text-decoration: none;
        font-weight: 700;
        z-index: 1000;
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid #fff;
        outline-offset: 2px;
      }

      .shell {
        width: min(100%, var(--max));
        margin: 0 auto;
        padding: 1rem 1rem 3rem;
      }

      header {
        position: sticky;
        top: 0;
        z-index: 20;
        backdrop-filter: blur(18px);
        background: linear-gradient(180deg, rgba(10, 13, 18, 0.96), rgba(10, 13, 18, 0.72));
        border-bottom: 1px solid rgba(57, 70, 95, 0.45);
      }

      .header-inner {
        width: min(100%, var(--max));
        margin: 0 auto;
        padding: 1rem;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 0.8rem;
        font-weight: 800;
        letter-spacing: 0.02em;
        text-decoration: none;
      }

      .brand-mark {
        width: 2.2rem;
        height: 2.2rem;
        border-radius: 14px;
        background: linear-gradient(135deg, var(--accent), var(--accent-2));
        box-shadow: 0 10px 30px rgba(122, 167, 255, 0.28);
      }

      nav ul {
        list-style: none;
        margin: 0;
        padding: 0;
        display: flex;
        flex-wrap: wrap;
        gap: 1rem;
      }

      nav a {
        color: var(--muted);
        text-decoration: none;
        padding: 0.6rem 0.8rem;
        border-radius: 999px;
