      nav a:hover,
      nav a:focus-visible {
        color: var(--text);
        background: rgba(255, 255, 255, 0.06);
        outline: none;
      }

      .hero {
        display: grid;
        grid-template-columns: 1.2fr 0.9fr;
        gap: 1.2rem;
        padding: 1.5rem 0 0.75rem;
        align-items: stretch;
      }

      .panel {
        background: linear-gradient(180deg, rgba(21, 26, 35, 0.94), rgba(15, 19, 27, 0.96));
        border: 1px solid var(--border);
        border-radius: var(--radius-xl);
        box-shadow: var(--shadow);
      }

      .hero-copy {
        padding: clamp(1.4rem, 4vw, 3rem);
        display: grid;
        gap: 1.25rem;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 0.55rem;
        width: fit-content;
        padding: 0.45rem 0.8rem;
        border: 1px solid var(--border);
        border-radius: 999px;
        color: var(--accent);
        background: rgba(155, 247, 211, 0.08);
        font-size: 0.92rem;
        font-weight: 700;
      }

      h1,
      h2,
      h3,
      p {
        margin: 0;
      }

      h1 {
        font-size: clamp(2.6rem, 6vw, 4.9rem);
        line-height: 0.96;
        letter-spacing: -0.04em;
        max-width: 11ch;
      }

      .hero-copy p {
        max-width: 58ch;
        color: var(--muted);
        font-size: 1.08rem;
      }

      .hero-actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.85rem;
      }

      .button,
      .button-secondary {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 0.55rem;
        min-height: 3rem;
        padding: 0.8rem 1.1rem;
        border-radius: 999px;
        border: 1px solid transparent;
        font-weight: 700;
        text-decoration: none;
      }

      .button {
        color: #06110d;
        background: linear-gradient(135deg, var(--accent), #c0ffe8);
      }

      .button-secondary {
        color: var(--text);
        border-color: var(--border-strong);
        background: rgba(255, 255, 255, 0.03);
      }

      .button:hover,
      .button-secondary:hover {
        transform: translateY(-1px);
      }

      .hero-stats {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 0.8rem;
      }

      .stat {
        padding: 1rem;
        border-radius: var(--radius-md);
        border: 1px solid var(--border);
        background: rgba(255, 255, 255, 0.03);
        min-width: 0;
      }

      .stat strong {
        display: block;
        font-size: 1.35rem;
      }

      .stat span {
        color: var(--muted);
        font-size: 0.94rem;
      }

      .hero-visual {
        padding: 1rem;
        display: grid;
        gap: 1rem;
        align-content: space-between;
        background:
          linear-gradient(180deg, rgba(17, 21, 29, 0.65), rgba(17, 21, 29, 0.92)),
          radial-gradient(circle at top, rgba(122, 167, 255, 0.22), transparent 60%);
      }

      .feature-card {
        position: relative;
        overflow: hidden;
        min-height: 100%;
        border-radius: calc(var(--radius-xl) - 8px);
        border: 1px solid var(--border);
        background:
          radial-gradient(circle at top left, rgba(155, 247, 211, 0.18), transparent 36%),
          linear-gradient(160deg, #1b2230 0%, #10151d 100%);
      }

      .feature-card .image {
        aspect-ratio: 4 / 3;
        display: grid;
        place-items: center;
        background:
          radial-gradient(circle at 30% 20%, rgba(255, 202, 122, 0.2), transparent 24%),
          radial-gradient(circle at 70% 65%, rgba(122, 167, 255, 0.26), transparent 25%);
        border-bottom: 1px solid rgba(57, 70, 95, 0.4);
      }

      .feature-card .content {
        padding: 1rem 1rem 1.1rem;
      }

      .pill-row {
        display: flex;
        flex-wrap: wrap;
        gap: 0.5rem;
      }

      .pill {
        border-radius: 999px;
        padding: 0.42rem 0.7rem;
        border: 1px solid var(--border);
        color: var(--muted);
        font-size: 0.88rem;
      }

      .section {
        padding-top: 1.5rem;
      }

      .section-header {
        display: flex;
        align-items: end;
        justify-content: space-between;
        gap: 1rem;
        margin-bottom: 0.95rem;
      }

      .section-header p {
        color: var(--muted);
        max-width: 55ch;
      }

      .section-header a {
        color: var(--accent);
        text-decoration: none;
        font-weight: 700;
      }

      .grid-products {
        display: grid;
        grid-template-columns: repeat(4, minmax(0, 1fr));
        gap: 1rem;
      }

      .card {
        min-width: 0;
        border-radius: var(--radius-lg);
        border: 1px solid var(--border);
        background: linear-gradient(180deg, rgba(21, 26, 35, 0.92), rgba(14, 17, 24, 0.96));
        overflow: hidden;
      }

      .card figure {
        margin: 0;
      }

      .card .art {
        display: grid;
        place-items: center;
        aspect-ratio: 1 / 1;
        border-bottom: 1px solid rgba(57, 70, 95, 0.4);
        background:
          radial-gradient(circle at 35% 30%, rgba(155, 247, 211, 0.18), transparent 18%),
          radial-gradient(circle at 70% 75%, rgba(122, 167, 255, 0.22), transparent 22%),
          linear-gradient(145deg, #151b25 0%, #0f131b 100%);
      }

      .card .body {
        padding: 1rem;
        display: grid;
        gap: 0.8rem;
      }

      .meta,
      .price-row {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 0.75rem;
      }

      .meta {
        color: var(--muted);
        font-size: 0.92rem;
      }

      .price {
        font-weight: 800;
        font-size: 1.08rem;
      }

      .strike {
        color: var(--muted-2);
        text-decoration: line-through;
      }

      .deal-grid {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 1rem;
      }

      .deal {
        padding: 1.2rem;
        display: grid;
        gap: 1rem;
        border-radius: var(--radius-lg);
        border: 1px solid var(--border);
        background:
