          linear-gradient(180deg, rgba(25, 31, 42, 0.95), rgba(15, 19, 27, 0.96));
      }

      .deal h3 {
        font-size: 1.45rem;
      }

      .deal p {
        color: var(--muted);
      }

      .deal .badge {
        width: fit-content;
        border-radius: 999px;
        padding: 0.35rem 0.7rem;
        font-weight: 700;
        color: #1f1404;
        background: linear-gradient(135deg, var(--accent-3), #ffe0aa);
      }

      .deal .cta {
        margin-top: auto;
        display: inline-flex;
        width: fit-content;
        align-items: center;
        gap: 0.45rem;
        color: var(--text);
        font-weight: 700;
        text-decoration: none;
      }

      .editorial-grid {
        display: grid;
        grid-template-columns: 1.1fr 0.9fr 0.9fr;
        gap: 1rem;
      }

      .story {
        overflow: hidden;
      }

      .story .image {
        aspect-ratio: 16 / 9;
        background:
          radial-gradient(circle at 25% 35%, rgba(255, 202, 122, 0.22), transparent 16%),
          radial-gradient(circle at 75% 30%, rgba(155, 247, 211, 0.22), transparent 20%),
          linear-gradient(135deg, #141924, #0f131b);
        border-bottom: 1px solid rgba(57, 70, 95, 0.4);
      }

      .story .copy {
        padding: 1rem;
        display: grid;
        gap: 0.6rem;
      }

      .story time {
        color: var(--muted-2);
        font-size: 0.9rem;
      }

      .newsletter {
        margin-top: 1.5rem;
        padding: 1.2rem;
        display: grid;
        gap: 1rem;
        border-radius: var(--radius-lg);
        border: 1px solid var(--border);
        background: linear-gradient(135deg, rgba(122, 167, 255, 0.12), rgba(155, 247, 211, 0.06));
      }

      form {
        display: flex;
        flex-wrap: wrap;
        gap: 0.8rem;
      }

      label {
        display: grid;
        gap: 0.35rem;
        color: var(--muted);
        font-weight: 600;
      }

      input[type="email"] {
        min-width: min(100%, 22rem);
        flex: 1 1 20rem;
        min-height: 3rem;
        padding: 0.8rem 1rem;
        color: var(--text);
        border-radius: 999px;
        border: 1px solid var(--border-strong);
        background: rgba(8, 11, 16, 0.92);
      }

      input[type="email"]::placeholder {
        color: var(--muted-2);
      }

      input[type="email"]:focus-visible,
      .button:focus-visible,
      .button-secondary:focus-visible,
      .cta:focus-visible,
      a:focus-visible {
        outline: 3px solid var(--accent);
        outline-offset: 3px;
      }

      .helper {
        color: var(--muted-2);
        font-size: 0.92rem;
      }

      footer {
        padding: 2rem 1rem 1rem;
        color: var(--muted);
      }

      .footer-inner {
        width: min(100%, var(--max));
        margin: 0 auto;
        padding-top: 1.25rem;
        border-top: 1px solid rgba(57, 70, 95, 0.5);
        display: flex;
        flex-wrap: wrap;
        justify-content: space-between;
        gap: 1rem;
      }

      .fineprint {
        max-width: 52ch;
      }

      svg {
        display: block;
      }

      .visual-svg {
        width: min(100%, 17rem);
      }

      @media (max-width: 1000px) {
        .hero,
        .grid-products,
        .editorial-grid {
          grid-template-columns: 1fr 1fr;
        }

        .hero {
          grid-template-columns: 1fr;
        }

        .hero-visual {
          min-height: 28rem;
        }
      }

      @media (max-width: 720px) {
        .header-inner,
        .section-header,
        .footer-inner {
          align-items: start;
          flex-direction: column;
        }

        nav ul {
          gap: 0.5rem;
        }

        .hero-stats,
        .grid-products,
        .deal-grid,
        .editorial-grid {
          grid-template-columns: 1fr;
        }

        h1 {
          max-width: none;
        }
      }

      @media (forced-colors: active) {
        :root {
          --bg: Canvas;
          --bg-elevated: Canvas;
          --bg-surface: Canvas;
          --bg-surface-2: Canvas;
          --border: ButtonBorder;
