          --danger: LinkText;
        }

        body,
        header,
        .panel,
        .card,
        .deal,
        .story,
        .newsletter,
        .stat {
          forced-color-adjust: auto;
          background: Canvas;
          color: CanvasText;
          border-color: ButtonBorder;
          box-shadow: none;
        }

        .button,
        .button-secondary,
        .skip-link {
          border: 1px solid ButtonText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <header>
      <div class="header-inner">
        <a class="brand" href="#" aria-label="Northstar Retail home">
          <span class="brand-mark" aria-hidden="true"></span>
          <span>Northstar Retail</span>
        </a>
        <nav aria-label="Primary">
          <ul>
            <li><a href="#featured">Featured</a></li>
            <li><a href="#deals">Deals</a></li>
            <li><a href="#journal">Journal</a></li>
            <li><a href="#join">Join list</a></li>
          </ul>
        </nav>
      </div>
    </header>

    <main id="main-content"></main>

    <footer>
      <div class="footer-inner">
        <p class="fineprint">
          Built for a premium retail brand with a dark editorial feel, accessible semantics, and responsive layout behavior.
        </p>
        <p>Northstar Retail &copy; 2026</p>
      </div>
    </footer>

    <script>
      const products = [
        {
          name: "Arc Runner Jacket",
          category: "Outerwear",
          price: "$248",
          compareAt: "$320",
          badge: "New season",
          accent: "#9bf7d3",
        },
        {
          name: "Mono Field Sneaker",
          category: "Footwear",
          price: "$168",
          compareAt: "$210",
          badge: "Best seller",
          accent: "#7aa7ff",
        },
        {
          name: "Studio Knit Crew",
          category: "Layers",
          price: "$98",
          compareAt: "$128",
          badge: "Limited run",
          accent: "#ffca7a",
        },
        {
          name: "Form Carry Tote",
          category: "Accessories",
          price: "$74",
          compareAt: "$92",
          badge: "Editor pick",
          accent: "#ff7a90",
        },
      ];

      const deals = [
        {
          title: "48-hour studio sale",
          body: "Take 20% off select outerwear and layering staples while the archive refreshes.",
          badge: "Save 20%",
        },
        {
          title: "Bundle the look",
          body: "Build a complete outfit and save more when you pair footwear with accessories.",
          badge: "Bundle offer",
        },
      ];

      const stories = [
        {
          title: "Inside the new minimal wardrobe",
          tag: "Design notes",
          date: "Apr 28",
          datetime: "2026-04-28",
          body: "A closer look at clean silhouettes, tactile materials, and why fewer pieces can do more work.",
        },
        {
          title: "How to layer for city evenings",
          tag: "Style guide",
          date: "May 01",
          datetime: "2026-05-01",
          body: "Balance warmth and movement with streamlined layers, tonal color, and durable finishing details.",
        },
        {
          title: "From the fitting room to the street",
          tag: "Editorial",
          date: "May 04",
          datetime: "2026-05-04",
          body: "See the season's strongest combinations styled for weekdays, weekends, and everything in between.",
        },
      ];

      let svgIdCounter = 0;

      const productSvg = (accent) => {
        const gradientId = `g-${++svgIdCounter}`;

        return `
        <svg class="visual-svg" viewBox="0 0 360 360" aria-hidden="true" focusable="false">
          <defs>
            <linearGradient id="${gradientId}" x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" stop-color="${accent}" />
              <stop offset="100%" stop-color="#ffffff" stop-opacity="0.1" />
            </linearGradient>
          </defs>
          <rect x="26" y="26" width="308" height="308" rx="54" fill="url(#${gradientId})" opacity="0.9" />
          <circle cx="120" cy="130" r="48" fill="rgba(255,255,255,0.15)" />
          <circle cx="238" cy="196" r="66" fill="rgba(255,255,255,0.09)" />
          <path d="M98 208c30-48 62-72 98-72 30 0 58 14 86 42" fill="none" stroke="#fff" stroke-width="16" stroke-linecap="round" opacity="0.8" />
          <path d="M115 254c28-20 57-30 89-30 28 0 52 7 74 21" fill="none" stroke="#fff" stroke-width="14" stroke-linecap="round" opacity="0.55" />
        </svg>`;
      };

      const sectionTitle = (id, title, description, linkText, link) => `
        <div class="section-header">
          <div>
            <h2 id="${id}">${title}</h2>
            <p>${description}</p>
          </div>
          <a href="${link}">${linkText}</a>
        </div>
      `;

      const productCard = (product) => `
        <article class="card">
          <figure>
            <div class="art">${productSvg(product.accent)}</div>
            <figcaption class="body">
              <div class="meta">
                <span>${product.category}</span>
                <span class="pill">${product.badge}</span>
              </div>
              <div>
                <h3>${product.name}</h3>
              </div>
              <div class="price-row">
                <span class="price">${product.price}</span>
                <span class="strike">${product.compareAt}</span>
              </div>
            </figcaption>
          </figure>
        </article>
      `;

      const dealCard = (deal, index) => `
        <article class="deal">
          <span class="badge">${deal.badge}</span>
          <h3>${deal.title}</h3>
          <p>${deal.body}</p>
          <a class="cta" href="#featured" aria-label="Shop featured products for ${deal.title.toLowerCase()}">
            Shop featured
            <span aria-hidden="true">→</span>
          </a>
        </article>
      `;

      const storyCard = (story) => `
        <article class="card story">
          <div class="image" aria-hidden="true"></div>
          <div class="copy">
            <div class="meta">
              <span>${story.tag}</span>
